import{_ as i,C as n,o as s,c,j as o,a as e,E as d,w as a,al as r}from"./chunks/framework.BawR2jEz.js";const x=JSON.parse('{"title":"Замена","description":"Массовая замена строк во всех сущностях exDoc с предварительным просмотром, выбором конкретных совпадений и подтверждением.","frontmatter":{"title":"Замена","description":"Массовая замена строк во всех сущностях exDoc с предварительным просмотром, выбором конкретных совпадений и подтверждением."},"headers":[],"relativePath":"search/replace.md","filePath":"search/replace.md"}'),p={name:"search/replace.md"};function u(h,t,b,g,f,S){const l=n("KbdShortcut");return s(),c("div",null,[t[8]||(t[8]=o("h1",{id:"замена",tabindex:"-1"},[e("Замена "),o("a",{class:"header-anchor",href:"#замена","aria-label":'Permalink to "Замена"'},"​")],-1)),t[9]||(t[9]=o("p",null,"Режим замены позволяет за одну операцию переименовать строку — например, CSS-класс, имя переменной, ссылку — сразу во всех найденных местах. Перед выполнением показывается превью, можно отметить только нужные совпадения и подтвердить операцию.",-1)),t[10]||(t[10]=o("h2",{id:"как-включить",tabindex:"-1"},[e("Как включить "),o("a",{class:"header-anchor",href:"#как-включить","aria-label":'Permalink to "Как включить"'},"​")],-1)),o("p",null,[t[1]||(t[1]=e("Откройте поиск, наберите запрос и переключитесь в режим замены кнопкой справа от строки ввода (горячая клавиша ",-1)),d(l,null,{default:a(()=>[...t[0]||(t[0]=[e("Ctrl+H",-1)])]),_:1}),t[2]||(t[2]=e("). Под полем поиска появится строка для ввода значения замены.",-1))]),t[11]||(t[11]=r('<p>Если кнопки режима замены нет — у вашей роли нет разрешения. Запросите его у администратора (см. <a href="./../settings/roles.html">Роли</a>).</p><h2 id="что-заменяется" tabindex="-1">Что заменяется <a class="header-anchor" href="#что-заменяется" aria-label="Permalink to &quot;Что заменяется&quot;">​</a></h2><p>Замена работает в тех же областях, что и обычный поиск: названия, хэштеги, шаблоны, стили, скрипты, ссылки на ресурсы. Затрагиваются все 12 типов сущностей exDoc.</p><h2 id="настроики-замены" tabindex="-1">Настройки замены <a class="header-anchor" href="#настроики-замены" aria-label="Permalink to &quot;Настройки замены&quot;">​</a></h2><p>Те же три переключателя, что в обычном поиске, применяются и к замене:</p><ul><li><strong>С учётом регистра</strong> — <code>Block</code> заменит только «Block», не тронет «block».</li><li><strong>Целое слово</strong> — заменяет только полные слова, не подстроки.</li><li><strong>Регулярное выражение</strong> — позволяет использовать паттерны и обратные ссылки в строке замены (<code>$1</code>, <code>$2</code>).</li></ul>',6)),o("p",null,[t[4]||(t[4]=e("В строке замены — дополнительный переключатель ",-1)),t[5]||(t[5]=o("strong",null,"Сохранять регистр",-1)),t[6]||(t[6]=e(" (",-1)),d(l,null,{default:a(()=>[...t[3]||(t[3]=[e("Alt+P",-1)])]),_:1}),t[7]||(t[7]=e("). Когда включён, регистр оригинала сохраняется в замене.",-1))]),t[12]||(t[12]=r('<table tabindex="0"><thead><tr><th>Найдено</th><th>Заменить <code>block</code> → <code>widget</code> (с сохранением регистра)</th><th>Результат</th></tr></thead><tbody><tr><td><code>block</code></td><td>строчное → строчное</td><td><code>widget</code></td></tr><tr><td><code>Block</code></td><td>Первая заглавная → Первая заглавная</td><td><code>Widget</code></td></tr><tr><td><code>BLOCK</code></td><td>ВСЁ ЗАГЛАВНОЕ → ВСЁ ЗАГЛАВНОЕ</td><td><code>WIDGET</code></td></tr><tr><td><code>BlOcK</code></td><td>смешанное → как написано</td><td><code>widget</code></td></tr></tbody></table><p>Полезно когда переименовываешь идентификатор, который встречается в нескольких регистрах: классы, переменные, имена сущностей. Без этой опции пришлось бы делать три отдельных замены.</p><p>Опция несовместима с <strong>С учётом регистра</strong> (поиск уже точный — нечего «преобразовывать») и <strong>Регулярным выражением</strong> (там работают обратные ссылки <code>$1</code>/<code>$2</code> со своей логикой). В обоих случаях переключатель серый и недоступен.</p><h2 id="превью-и-выбор" tabindex="-1">Превью и выбор <a class="header-anchor" href="#превью-и-выбор" aria-label="Permalink to &quot;Превью и выбор&quot;">​</a></h2><p>После ввода строки поиска и строки замены через секунду появляется список совпадений. Каждое — отдельная карточка с информацией:</p><ul><li>тип сущности и её имя (или хэштег);</li><li>название поля, в котором найдено совпадение;</li><li>фрагмент исходного текста (~100 символов до и после) с подсветкой того, что найдено и того, чем оно станет;</li><li>если в одном поле несколько совпадений — показано их количество.</li></ul><p>По умолчанию все совпадения отмечены. Снимите галочки с тех, которые <strong>не</strong> должны меняться. Над списком — кнопка «Выбрать все / Снять все» и счётчик отмеченных.</p><p>Если совпадений слишком много (больше 1000), показываются первые — уточните запрос, чтобы увидеть остальные.</p><h2 id="выполнение-замены" tabindex="-1">Выполнение замены <a class="header-anchor" href="#выполнение-замены" aria-label="Permalink to &quot;Выполнение замены&quot;">​</a></h2><p>Кнопка <strong>Заменить выбранные</strong> в верхней панели запускает операцию. Перед этим открывается окно подтверждения со сводкой:</p><ul><li>что ищется и на что меняется;</li><li>настройки (регистр, целое слово, регулярное выражение);</li><li>количество затронутых полей;</li><li>обязательная отметка «Я понимаю, что это изменит данные».</li></ul><p>После подтверждения замена выполняется в одной транзакции базы. Если хотя бы одно изменение не удалось — откатываются все. По завершении показывается баннер с числом заменённых полей и информацией о пропущенных или ошибочных.</p><p>После успешной замены автоматически перестраиваются стили (если меняли SCSS), скрипты (если JS) и очищается кэш шаблонов (если TWIG). Дополнительных действий делать не нужно.</p><h2 id="ограничения" tabindex="-1">Ограничения <a class="header-anchor" href="#ограничения" aria-label="Permalink to &quot;Ограничения&quot;">​</a></h2><ul><li>Замена работает только в базе данных. SCSS-файлы и JS-файлы на диске не затрагиваются.</li><li>Каталог сайта (фронт) не редактируется — только админ-сущности exDoc.</li><li>Откат замены вручную не предусмотрен. Перед массовой заменой убедитесь, что у вас есть резервная копия.</li><li>В полях, хранящих JSON (например, список ссылок), замена применяется к сериализованному значению. Если результат окажется невалидным JSON, такое поле пропускается с пометкой об ошибке — данные не повреждаются.</li></ul><h2 id="советы" tabindex="-1">Советы <a class="header-anchor" href="#советы" aria-label="Permalink to &quot;Советы&quot;">​</a></h2><ul><li>Сначала попробуйте обычный поиск с теми же настройками, чтобы понять охват замены.</li><li>Включайте <strong>С учётом регистра</strong>, если переименовываете идентификатор (CSS-класс, переменную) — иначе можно случайно тронуть текстовые упоминания.</li><li>Включайте <strong>Целое слово</strong>, чтобы <code>block</code> не задел <code>blockchain</code>, <code>unblock</code> и подобные.</li><li>При сложных переименованиях с шаблонной заменой используйте <strong>Регулярное выражение</strong> и обратные ссылки в строке замены: например, <code>prefix-(\\w+)</code> → <code>new-prefix-$1</code>.</li></ul><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./">Поиск</a> — обычный поиск без замены</li><li><a href="./../settings/roles.html">Роли</a> — выдача разрешения на замену</li></ul>',19))])}const k=i(p,[["render",u]]);export{x as __pageData,k as default};
